package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type TempRec struct { // 01 TEMP-REC, 8 bytes
	TcSensor string          // PIC X(4) @0 len=4
	TcF      decimal.Decimal // PIC 9(3)V9 @4 len=4
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"                     // PIC X len=1 = "N"
var WsC decimal.Decimal = decimal.New(0, 0)    // PIC S9(3)V99 len=5 = 0
var WsFreeze int64 = 0                         // PIC 99 len=2 = 0
var WsCount int64 = 0                          // PIC 99 len=2 = 0
var WsFEd string                               // PIC ZZ9.9 len=5
var WsCEd string                               // PIC -ZZ9.99 len=7

var TempRecData TempRec
var tempLines []string
var lineIdx int

func init() {
	decimal.DivisionPrecision = 16
}

func parsePic9V9(s string) decimal.Decimal {
	// PIC 9(3)V9 -> 4 digits scale 1, pad spaces as '0'
	cleaned := strings.ReplaceAll(s, " ", "0")
	if cleaned == "" {
		return decimal.New(0, 0)
	}
	n, err := strconv.ParseInt(cleaned, 10, 64)
	if err != nil {
		return decimal.New(0, 0)
	}
	return decimal.New(n, -1)
}

func storeS9_3V99(d decimal.Decimal) decimal.Decimal {
	if d.IsZero() {
		return decimal.New(0, 0)
	}
	sign := d.Sign()
	abs := d.Abs()
	s := abs.StringFixed(2)
	parts := strings.SplitN(s, ".", 2)
	ip := parts[0]
	fp := "00"
	if len(parts) > 1 {
		fp = parts[1]
	}
	if len(ip) > 3 {
		ip = ip[len(ip)-3:]
	}
	reconStr := ip + "." + fp
	recon, err := decimal.NewFromString(reconStr)
	if err != nil {
		return d
	}
	if sign < 0 {
		recon = recon.Neg()
		if recon.IsZero() {
			recon = decimal.New(0, 0)
		}
	}
	return recon
}

func formatEdited(value decimal.Decimal, intDigits int, decDigits int, signed bool, intPic string) string {
	isNeg := value.Sign() < 0
	absVal := value.Abs()
	var intStr, fracStr string
	if decDigits > 0 {
		s := absVal.StringFixed(int32(decDigits))
		parts := strings.SplitN(s, ".", 2)
		intStr = parts[0]
		if len(parts) > 1 {
			fracStr = parts[1]
		} else {
			fracStr = strings.Repeat("0", decDigits)
		}
	} else {
		intStr = absVal.StringFixed(0)
		fracStr = ""
	}
	if len(intStr) > intDigits {
		intStr = intStr[len(intStr)-intDigits:]
	} else if len(intStr) < intDigits {
		intStr = strings.Repeat("0", intDigits-len(intStr)) + intStr
	}
	editedInt := make([]byte, intDigits)
	suppressed := true
	for i := 0; i < intDigits; i++ {
		picChar := byte('9')
		if i < len(intPic) {
			picChar = intPic[i]
		}
		digitChar := intStr[i]
		if picChar == 'Z' {
			if suppressed && digitChar == '0' {
				editedInt[i] = ' '
			} else {
				editedInt[i] = digitChar
				suppressed = false
			}
		} else {
			editedInt[i] = digitChar
			if digitChar != '0' {
				suppressed = false
			}
		}
	}
	var sb strings.Builder
	if signed {
		if isNeg {
			sb.WriteByte('-')
		} else {
			sb.WriteByte(' ')
		}
	}
	sb.Write(editedInt)
	if decDigits > 0 {
		sb.WriteByte('.')
		if len(fracStr) > decDigits {
			fracStr = fracStr[:decDigits]
		} else if len(fracStr) < decDigits {
			fracStr = fracStr + strings.Repeat("0", decDigits-len(fracStr))
		}
		sb.WriteString(fracStr)
	}
	return sb.String()
}

func formatZZ9_9(v decimal.Decimal) string {
	return formatEdited(v, 3, 1, false, "ZZ9")
}

func formatMinusZZ9_99(v decimal.Decimal) string {
	return formatEdited(v, 3, 2, true, "ZZ9")
}

func formatPIC99(v int64) string {
	m := v % 100
	if m < 0 {
		m = -m
	}
	return fmt.Sprintf("%02d", m)
}

func openTempFile() {
	f, err := os.Open("input.dat")
	if err != nil {
		tempLines = []string{}
		lineIdx = 0
		return
	}
	defer f.Close()
	scanner := bufio.NewScanner(f)
	tempLines = []string{}
	for scanner.Scan() {
		tempLines = append(tempLines, scanner.Text())
	}
	if err := scanner.Err(); err != nil {
		fmt.Fprintf(os.Stderr, "error reading input.dat: %v\n", err)
		os.Exit(1)
	}
	lineIdx = 0
}

func closeTempFile() {
}

func readPara() {
	if lineIdx >= len(tempLines) {
		WsEofFlag = "Y"
		return
	}
	line := tempLines[lineIdx]
	lineIdx++
	if len(line) < 8 {
		line = line + strings.Repeat(" ", 8-len(line))
	} else if len(line) > 8 {
		line = line[:8]
	}
	TempRecData.TcSensor = line[0:4]
	rawF := line[4:8]
	TempRecData.TcF = parsePic9V9(rawF)
}

func processPara() {
	diff := TempRecData.TcF.Sub(decimal.NewFromInt(32))
	mult := diff.Mul(decimal.NewFromInt(5))
	div := mult.Div(decimal.NewFromInt(9))
	rounded := div.Round(2)
	WsC = storeS9_3V99(rounded)
	if WsC.Sign() < 0 {
		WsFreeze++
		WsFreeze = WsFreeze % 100
	}
	WsCount++
	WsCount = WsCount % 100
	WsFEd = formatZZ9_9(TempRecData.TcF)
	WsCEd = formatMinusZZ9_99(WsC)
	line := TempRecData.TcSensor + " " + WsFEd + "F " + WsCEd + "C"
	fmt.Println(line)
	readPara()
}

func mainPara() {
	openTempFile()
	readPara()
	for WsEofFlag != "Y" {
		processPara()
	}
	closeTempFile()
	countStr := formatPIC99(WsCount)
	freezeStr := formatPIC99(WsFreeze)
	fmt.Println("READINGS: " + countStr + " BELOW ZERO: " + freezeStr)
}

func main() {
	mainPara()
}
